<script setup lang="ts">
import {mailboxErrorMessage} from '../settings';
import CalendarExport from '../components/CalendarExport.vue';
import {onMounted,ref} from 'vue';import {request,waitJob,errorText} from '../api';import type {Account} from '../types';import {displayTime,statusNames,setDisplayTimezone} from '../domain';import Icon from '../components/Icon.vue';import AccountConnect from '../components/AccountConnect.vue';import ReminderSettings from '../components/ReminderSettings.vue';import AISettings from '../components/AISettings.vue';import WebhookSettings from '../components/WebhookSettings.vue';
defineEmits<{onboarding:[]}>();const settings=ref<any>(),accounts=ref<Account[]>([]),diagnostics=ref<any>(),error=ref(''),message=ref(''),busy=ref(false),showConnect=ref(false),credential=ref(''),restore=ref<any>(),upload=ref<HTMLInputElement>();
async function load(){try{[settings.value,accounts.value,diagnostics.value]=await Promise.all([request('/settings'),request('/accounts'),request('/diagnostics')]);}catch(e){error.value=errorText(e);}}
async function perform(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn();await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function save(changes:Record<string,unknown>){await perform(async()=>{await request('/settings','PATCH',{expected_version:settings.value.version,changes});if(changes.timezone)setDisplayTimezone(String(changes.timezone));message.value='设置已保存。';});}
async function jobAction(path:string,body:unknown,done:string){await perform(async()=>{const j=await request(path,'POST',body);if(j.job_id??j.sync_run_id)await waitJob(j.job_id??j.sync_run_id);message.value=done;});}
async function exportData(type:string){await perform(async()=>{const j=await request(type==='backup'?'/backups':'/exports','POST',type==='backup'?{include_evidence:false}:{format:type,entities:['tasks','applications']});const result=await waitJob(j.job_id);const id=result.result?.artifact_id??result.result_ref??result.artifact_id;if(!id)throw new Error('导出已完成，但下载地址不可用，请查看诊断。');const a=document.createElement('a');a.href=`/api/v1/artifacts/${id}`;a.download='';a.click();message.value='导出已就绪。备份包含个人事项，请保存在私密位置。';});}
async function restoreFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;await perform(async()=>{const form=new FormData();form.append('backup',f);const j=await request('/restores/validate','POST',form);const result=await waitJob(j.job_id);const id=result.result?.restore_id??result.restore_id??j.restore_id??j.job_id;restore.value=await request(`/restores/${id}`);restore.value.id??=id;});if(upload.value)upload.value.value='';}
async function applyRestore(){if(!confirm('将以备份替换当前数据，并要求重新授权邮箱。是否继续？'))return;busy.value=true;error.value='';try{const r=restore.value;const j=await request(`/restores/${r.id}/apply`,'POST',{confirmation_token:r.confirmation_token});restore.value=null;if(!j.session_reset&&j.job_id)await waitJob(j.job_id);message.value='恢复完成。请从 OfferPilot 托盘重新打开界面，并重新授权邮箱。';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function purge(scope:string){busy.value=true;error.value='';try{const preview=await request('/privacy/preview','POST',{scope});if(!confirm('即将清理：'+(scope==='all'?'全部本机个人数据':scope==='mail_cache'?'邮件缓存':'来源证据')+'。已有下载到其他位置的导出文件需自行删除。\n影响数量：'+JSON.stringify(preview.counts)+'\n是否继续？'))return;const result=await request('/privacy/purge','POST',{scope,preview_token:preview.preview_token});message.value=scope==='all'?'本机个人数据已删除，请从托盘重新打开。':'清理已完成。';if(scope!=='all'&&!result.session_reset)await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function remove(a:Account){if(!confirm('移除邮箱并删除授权码？已有任务将保留。'))return;await perform(async()=>{const j=await request(`/accounts/${a.id}`,'DELETE',{expected_version:a.version});if(j.job_id)await waitJob(j.job_id);message.value='邮箱已移除，已有任务保持不变。';});}
async function connected(tested:boolean){showConnect.value=false;await load();message.value=tested?'邮箱登录和只读收件箱测试成功，正文同步将在后台继续。':'邮箱已保存，但连接测试未通过。请检查网络或更新授权码后重试。';}
async function exportDiagnostics(){await perform(async()=>{const job=await request('/diagnostics/export','POST',{});const result=await waitJob(job.job_id);const link=document.createElement('a');link.href='/api/v1/artifacts/'+result.result.artifact_id;link.download='';link.click();message.value='诊断包已就绪，请检查内容后再决定是否分享。';});}
onMounted(load);
</script>
<template><section class="page settings-page"><div class="page-eyebrow"><span class="tiny-line"/>按你的方式工作</div><div class="page-heading"><div><h1>设置与诊断</h1><p>连接、提醒和数据，都由你掌控。</p></div><button class="button" @click="$emit('onboarding')">重新查看引导</button></div><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="message" class="success-box" role="status">{{message}}</p><div class="settings-grid"><section class="setting-card"><div class="card-title"><Icon name="mail"/><h2>邮箱连接</h2></div><AccountConnect v-if="!accounts.length||showConnect" @connected="connected"/><div v-for="a in accounts" :key="a.id"><div class="account-head"><strong>{{a.address}}</strong><span class="badge">{{statusNames[a.state]??a.state}}</span></div><dl class="details"><dt>上次同步</dt><dd>{{displayTime(a.last_sync_at)}}</dd><dt>下一次扫描</dt><dd>{{displayTime(a.next_sync_at)}}</dd></dl><p v-if="a.last_error_code" class="error-box">{{mailboxErrorMessage(a.last_error_code)}}</p><div class="button-row"><button class="button" :disabled="busy" @click="jobAction('/sync/trigger',{account_id:a.id},'同步完成。')">立即同步</button><button class="button" :disabled="busy" @click="jobAction('/accounts/'+a.id+'/test',undefined,'登录与只读收件箱测试成功。正文同步结果请查看邮箱状态。')">测试连接</button><button class="button" :disabled="busy" @click="perform(async()=>{await request(`/accounts/${a.id}`,'PATCH',{expected_version:a.version,paused:a.state!=='paused'})})">{{a.state==='paused'?'恢复同步':'暂停同步'}}</button></div><details class="advanced"><summary>更新授权码或移除账户</summary><label>新的授权码<input v-model="credential" type="password" autocomplete="new-password"/></label><div class="button-row"><button class="button" :disabled="busy||!credential" @click="perform(async()=>{try{await request(`/accounts/${a.id}/credential`,'PUT',{authorization_code:credential});message='授权码已更新。'}finally{credential=''}})">更新授权码</button><button class="text-button danger" :disabled="busy" @click="remove(a)">移除邮箱</button></div></details></div><button v-if="accounts.length" class="button" @click="showConnect=!showConnect">{{showConnect?'收起连接表单':'连接另一个邮箱'}}</button><p class="field-help">只读获取 INBOX，不发送、删除或归档邮件。</p></section><AISettings @changed="load"/><WebhookSettings @changed="load"/><section v-if="settings" class="setting-card"><div class="card-title"><Icon name="bell"/><h2>提醒与运行</h2></div><label class="setting-toggle"><span><strong>Windows 系统通知</strong><small>应用内记录始终保留</small></span><input type="checkbox" :checked="settings.notifications_enabled" :disabled="busy" @change="save({notifications_enabled:($event.target as HTMLInputElement).checked})"/></label><button class="button" :disabled="busy" @click="jobAction('/notifications/test',{channel:'windows'},'测试已提交，请检查系统通知。')">发送测试通知</button><div class="setting-divider"/><label>省略年份时默认使用<input type="number" min="2000" max="2099" step="1" :value="settings.default_event_year" :disabled="busy" @change="save({default_event_year:Number(($event.target as HTMLInputElement).value)})"/></label><p class="field-help">当前默认 {{settings.default_event_year}} 年，每年可在这里调整一次。只用于新识别的省略年份内容，已保存事件保持原日期。</p><label>显示时区<select :value="settings.timezone" :disabled="busy" @change="save({timezone:($event.target as HTMLSelectElement).value})"><option value="Asia/Shanghai">北京时间</option><option value="Asia/Tokyo">东京时间</option><option value="UTC">UTC</option><option value="America/New_York">纽约时间</option></select></label><label>邮箱扫描间隔<select :value="settings.sync_interval_seconds" :disabled="busy" @change="save({sync_interval_seconds:Number(($event.target as HTMLSelectElement).value)})"><option :value="120">每 2 分钟</option><option :value="180">每 3 分钟（推荐）</option><option :value="300">每 5 分钟</option></select></label><label class="setting-toggle"><span><strong>登录 Windows 后自动运行</strong><small>只显示托盘，不自动打开窗口</small></span><input type="checkbox" :checked="settings.autostart_enabled" :disabled="busy" @change="save({autostart_enabled:($event.target as HTMLInputElement).checked})"/></label><p class="field-help">关闭窗口后托盘仍在运行。休眠、关机或显式退出后，不能保证准时提醒。</p><ReminderSettings :settings="settings" :busy="busy" @save="save"/></section><section class="setting-card"><div class="card-title"><Icon name="download"/><h2>数据导出与备份</h2></div><p class="muted">备份保留任务和必要来源信息，排除邮箱授权码、AI 密钥及手机通知地址。恢复后需重新授权邮箱，并重新启用外部服务。</p><div class="button-row wrap"><button class="button" :disabled="busy" @click="exportData('csv')">导出 CSV</button><button class="button" :disabled="busy" @click="exportData('json')">导出 JSON</button><button class="button primary" :disabled="busy" @click="exportData('backup')">下载备份</button></div><CalendarExport/><div class="setting-divider"/><input ref="upload" type="file" accept=".zip" hidden @change="restoreFile"><button class="text-button" :disabled="busy" @click="upload?.click()"><Icon name="upload" :size="16"/>选择备份并校验</button><div v-if="restore" class="subtle-box"><strong>备份校验完成</strong><pre>{{restore.summary??restore.record_counts??'恢复会替换当前数据。'}}</pre><button class="button" :disabled="busy" @click="applyRestore">确认恢复这份备份</button></div></section><section class="setting-card"><div class="card-title"><Icon name="settings"/><h2>运行诊断</h2></div><p class="muted">本地服务、邮箱和通知的状态集中在这里。</p><div class="diagnostic-status"><i :class="{offline:!diagnostics}"/>{{diagnostics?'本地服务已连接':'服务状态不可用'}}</div><button class="button" :disabled="busy" @click="load">刷新状态</button><details class="advanced"><summary>导出诊断包</summary><p class="field-help">包含应用版本、模块健康状态、数量统计与最多 2000 条脱敏运行日志；不包含业务数据库、邮件正文、邮箱地址、凭据或用户目录路径。仅下载到本机，不会自动上传。</p><button class="button" :disabled="busy" @click="exportDiagnostics">生成并下载诊断包</button></details><details class="advanced"><summary>查看诊断详情</summary><pre>{{JSON.stringify(diagnostics,null,2)}}</pre></details><details class="advanced"><summary>隐私与本地数据清理</summary><p class="field-help">清缓存保留任务；删除全部数据会停止连接并重新进入向导。</p><div class="button-row wrap"><button class="button" :disabled="busy" @click="purge('mail_cache')">清除邮件缓存</button><button class="button" :disabled="busy" @click="purge('source_evidence')">删除来源证据</button><button class="text-button danger" :disabled="busy" @click="purge('all')">删除全部本机数据</button></div></details><p class="field-help">AI 和手机通知默认关闭。只有明确启用后，才会向设置中的服务发送说明范围内的内容。</p></section></div></section></template>
